"""Form widgets — group validated ``Field``s and gate submission.

A ``Form`` lays out its ``Field``s (each wrapping an input) and any other widgets
(e.g. a submit ``Button``). On submit it validates every field; ``on_submit`` is
called **only when all pass**, with a dict of ``{field name: value}``. Validation
also runs on blur, and field errors render below the input — set via
``textContent`` (never ``innerHTML``), so they can't inject markup.
"""
from __future__ import annotations

from typing import Any, Callable

from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class Field(BaseWidget):
    """One labelled, validated field — wraps an input (``TextInput``, ``Select``,
    …) with a ``name``, an optional ``label``, and a list of ``validators`` (see
    :mod:`workpeg.ui.validators`). Valid only as a direct child of ``Form``::

        Field("email", TextInput(value=self.email, on_change=self.set_email),
              label="Email", validators=[required, email])

    Validation runs on blur and on submit; the error renders below the input.
    ``validators`` may mix the built-ins with a **custom** ``lambda value: <error
    message or None>`` — a lambda closes over ``this``, so it can read your
    ``State`` (e.g. a list of names already taken).
    """

    widget_type = "Field"

    def __init__(
        self,
        name: str,
        child: WidgetChild,
        *,
        label: str | Binding | None = None,
        validators: list | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.name = name
        self.child = child
        self.label = label
        self.validators = validators or []

    def children(self) -> list[WidgetChild]:
        return [self.child]


class Form(BaseWidget):
    """A form grouping ``Field``s (plus any other widgets, e.g. a submit button).
    On submit every field is validated; ``on_submit(values)`` runs only when all
    pass, with ``values`` a dict of ``{field name: value}``. Add a
    ``Button(kind="submit")`` to submit (Enter in a text field submits too)::

        Form(
            Field("email", TextInput(...), label="Email",
                  validators=[required, email]),
            Field("password", TextInput(type="password"), label="Password",
                  validators=[required, min_length(8)]),
            Button("Sign up", kind="submit"),
            on_submit=self.submit,
        )
    """

    widget_type = "Form"

    def __init__(
        self,
        *children: WidgetChild,
        on_submit: Callable | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self._children = children
        self.on_submit = on_submit

    def children(self) -> list[WidgetChild]:
        return list(self._children)
